// Ported from core/src/evaluation/splits.ts (P10-T08; ARCH §9; V-P10-5/6):
// evaluation splits.
//
// A frozen benchmark split is a versioned, reproducible SELECTION over a
// dataset: seed + dataset version pin the selection so the exact benchmark rows
// can be regenerated byte-identically forever — the split manifest is data, not
// a snapshot copy of the cases. Selection uses a tiny seeded PRNG (mulberry32)
// over a stable case_id sort; `Math.random` appears nowhere (determinism is a
// hard requirement, not a nicety).
//
// The rolling split (recent-window evaluation) prefers real timestamps keyed
// by case_id; when the dataset carries no timestamps at all it falls back to
// the ROLLING_FALLBACK_COUNT last rows in insertion order (declared in the
// result's Mode — the fallback is never silent).
//
// Contamination check (V-P10-6): benchmark rows must never overlap
// candidate-training feedback — the disjointness of frozen case ids against
// the label-id set consumed as training evidence is checked explicitly and
// violations are reported, never swallowed.
package evaluation

import (
	"fmt"
	"math"
	"sort"
	"time"
)

// FrozenSplitFraction is the frozen-split selection fraction (versioned data,
// D11-adjacent): the seeded selection takes `round(n * FROZEN_SPLIT_FRACTION)`
// rows of the stable-sorted dataset. Exported, never silently hard-coded.
const FrozenSplitFraction = 0.5

// RollingFallbackCount is the rolling-split fallback size (versioned data):
// when timestamps are absent, the last N rows in insertion order form the
// rolling split. Exported, never silently hard-coded.
const RollingFallbackCount = 20

// DayMs is one day in milliseconds (DAY_MS).
const DayMs = 24 * 60 * 60 * 1000

// Mulberry32 is the deterministic mulberry32 PRNG — tiny, seedable, no
// dependencies. The returned func yields floats in [0, 1) exactly as the TS
// mulberry32 did (uint32 wraparound arithmetic, identical bit operations).
func Mulberry32(seed int) func() float64 {
	state := uint32(seed)
	return func() float64 {
		state += 0x6d2b79f5
		t := state
		t = (t ^ (t >> 15)) * (t | 1)
		t ^= t + (t^(t>>7))*(t|61)
		return float64((t ^ (t >> 14))) / 4294967296
	}
}

// FrozenSplitManifest is the frozen-split manifest — the versioned selection
// record (data, not code).
type FrozenSplitManifest struct {
	DatasetVersion string   `json:"dataset_version"`
	Seed           int      `json:"seed"`
	SplitID        string   `json:"split_id"`
	CaseIDs        []string `json:"case_ids"`
	CreatedAt      string   `json:"created_at"`
}

// FrozenSplitOptions pins the seed, dataset version and the injected instant.
type FrozenSplitOptions struct {
	Seed           int
	DatasetVersion string
	// CreatedAt is the injected instant (ISO-8601) stamped on the manifest —
	// never generated.
	CreatedAt string
}

// RollingSplitMode values declare which selection lane produced a rolling
// split.
const (
	RollingSplitModeTimestampWindow = "timestamp-window"
	RollingSplitModeLastNFallback   = "last-n-fallback"
)

// RollingSplitResult carries the rolling split with its declared lane.
type RollingSplitResult struct {
	// Mode declares which selection lane produced the result.
	Mode       string   `json:"mode"`
	WindowDays int      `json:"window_days"`
	Now        string   `json:"now"`
	CaseIDs    []string `json:"case_ids"`
	// ExcludedWithoutTimestamp counts the rows excluded for lacking a
	// parseable timestamp (timestamp lane only).
	ExcludedWithoutTimestamp int `json:"excluded_without_timestamp"`
}

// RollingSplitOptions carries the window, the injected "now" and the optional
// case_id → ISO-8601 timestamp map (e.g. run `finished_at`).
type RollingSplitOptions struct {
	WindowDays int
	// Now is the injected "now" instant (ISO-8601) bounding the window —
	// never generated.
	Now string
	// Timestamps is the optional case_id → ISO-8601 timestamp map.
	Timestamps map[string]string
}

// ContaminationResult is the contamination check result (V-P10-6) — violations
// are explicit ids.
type ContaminationResult struct {
	Disjoint   bool
	Violations []string
}

// stableCompare is the stable, locale-independent comparator.
func stableCompare(a, b string) int {
	return compareStrings(a, b)
}

// BuildFrozenSplit performs a deterministic seeded frozen-split selection:
// stable sort by case_id first, then a seeded Fisher-Yates shuffle picks
// `round(n * FrozenSplitFraction)` rows; the manifest carries the sorted
// selected case ids. Same seed + dataset version ⇒ byte-identical manifest.
func BuildFrozenSplit(cases []struct{ CaseID string }, opts FrozenSplitOptions) FrozenSplitManifest {
	ordered := make([]struct{ CaseID string }, len(cases))
	copy(ordered, cases)
	sort.SliceStable(ordered, func(i, j int) bool {
		return stableCompare(ordered[i].CaseID, ordered[j].CaseID) < 0
	})
	rng := Mulberry32(opts.Seed)
	indices := make([]int, len(ordered))
	for i := range indices {
		indices[i] = i
	}
	for i := len(indices) - 1; i > 0; i-- {
		j := int(rng() * float64(i+1))
		indices[i], indices[j] = indices[j], indices[i]
	}
	count := int(math.Round(float64(len(ordered)) * FrozenSplitFraction))
	caseIDs := make([]string, 0, count)
	for _, index := range indices[:count] {
		caseIDs = append(caseIDs, ordered[index].CaseID)
	}
	sort.SliceStable(caseIDs, func(i, j int) bool { return stableCompare(caseIDs[i], caseIDs[j]) < 0 })
	return FrozenSplitManifest{
		DatasetVersion: opts.DatasetVersion,
		Seed:           opts.Seed,
		SplitID:        fmt.Sprintf("frozen-%d-%s", opts.Seed, opts.DatasetVersion),
		CaseIDs:        caseIDs,
		CreatedAt:      opts.CreatedAt,
	}
}

// BuildRollingSplit builds the rolling split: cases whose timestamp falls
// inside `[now - windowDays, now]` (timestamp lane), or — when NO case carries a
// parseable timestamp — the last RollingFallbackCount rows in insertion order
// (declared fallback lane). Selected case ids are always returned sorted.
func BuildRollingSplit(cases []struct{ CaseID string }, opts RollingSplitOptions) (RollingSplitResult, error) {
	nowMs, err := parseInstant(opts.Now)
	if err != nil {
		return RollingSplitResult{}, fmt.Errorf("buildRollingSplit: 'now' is not a parseable ISO-8601 instant: %s", opts.Now)
	}
	if opts.Timestamps != nil {
		inWindow := []string{}
		withoutTimestamp := 0
		for _, evalCase := range cases {
			raw, present := opts.Timestamps[evalCase.CaseID]
			if !present {
				withoutTimestamp++
				continue
			}
			atMs, parseErr := parseInstant(raw)
			if parseErr != nil {
				continue
			}
			if atMs > nowMs || nowMs-atMs > int64(opts.WindowDays)*DayMs {
				continue
			}
			inWindow = append(inWindow, evalCase.CaseID)
		}
		if len(inWindow) > 0 || withoutTimestamp < len(cases) {
			sort.SliceStable(inWindow, func(i, j int) bool { return stableCompare(inWindow[i], inWindow[j]) < 0 })
			return RollingSplitResult{
				Mode:                     RollingSplitModeTimestampWindow,
				WindowDays:               opts.WindowDays,
				Now:                      opts.Now,
				CaseIDs:                  inWindow,
				ExcludedWithoutTimestamp: withoutTimestamp,
			}, nil
		}
	}
	// Declared fallback: no (usable) timestamps anywhere — last-N insertion order.
	start := len(cases) - RollingFallbackCount
	if start < 0 {
		start = 0
	}
	fallback := make([]string, 0, len(cases)-start)
	for _, evalCase := range cases[start:] {
		fallback = append(fallback, evalCase.CaseID)
	}
	sort.SliceStable(fallback, func(i, j int) bool { return stableCompare(fallback[i], fallback[j]) < 0 })
	return RollingSplitResult{
		Mode:                     RollingSplitModeLastNFallback,
		WindowDays:               opts.WindowDays,
		Now:                      opts.Now,
		CaseIDs:                  fallback,
		ExcludedWithoutTimestamp: len(cases) - len(fallback),
	}, nil
}

// parseInstant parses an ISO-8601 instant. JS Date.parse accepts a wider set of
// ISO-8601 spellings than Go's time.RFC3339 (e.g. date-only and space-
// separated forms); the RFC3339 family covers every instant the TS tests used
// (all `...Z` stamps).
func parseInstant(value string) (int64, error) {
	for _, layout := range []string{time.RFC3339Nano, time.RFC3339, "2006-01-02T15:04:05.000Z0700", "2006-01-02"} {
		if t, err := time.Parse(layout, value); err == nil {
			return t.UnixMilli(), nil
		}
	}
	return 0, fmt.Errorf("unparseable instant: %s", value)
}

// ContaminationCheck checks that benchmark (frozen) rows never overlap
// candidate-training feedback (V-P10-6). Returns the sorted intersection —
// Disjoint is true only when no frozen case id doubles as a training label id.
func ContaminationCheck(frozenCaseIDs, trainingFeedbackLabelIDs []string) ContaminationResult {
	training := map[string]bool{}
	for _, id := range trainingFeedbackLabelIDs {
		training[id] = true
	}
	seen := map[string]bool{}
	violations := []string{}
	for _, id := range frozenCaseIDs {
		if training[id] && !seen[id] {
			seen[id] = true
			violations = append(violations, id)
		}
	}
	sort.SliceStable(violations, func(i, j int) bool { return stableCompare(violations[i], violations[j]) < 0 })
	return ContaminationResult{Disjoint: len(violations) == 0, Violations: violations}
}
